// Some portions generated by Co-Pilot
import { beforeEach, describe, expect, it, vi } from "vitest";
import { loadLatestAssets } from "../fetchTemurinReleases";
import { createMockTemurinReleaseAPI } from "@/hooks/__fixtures__/hooks";
import { fetchLatestAssets } from "@/services/adoptiumApi";
import { getVersionAsString } from "../index";

vi.mock("@/services/adoptiumApi", () => ({ fetchLatestAssets: vi.fn() }));

describe("loadLatestAssets", () => {
  beforeEach(() => vi.clearAllMocks());

  it("requests the selected version and platform filters", async () => {
    const release = createMockTemurinReleaseAPI(false, "jdk");
    vi.mocked(fetchLatestAssets).mockResolvedValue([release]);
    expect(await loadLatestAssets(25, "linux", "x64")).toEqual([release]);
    expect(fetchLatestAssets).toHaveBeenCalledWith(25, {
      os: "linux",
      architecture: "x64",
    });
  });

  it("keeps source archives separate while retaining JDK, JRE and installer assets", async () => {
    const source = createMockTemurinReleaseAPI(false, "sources");
    const jdk = createMockTemurinReleaseAPI(true, "jdk");
    const jre = createMockTemurinReleaseAPI(true, "jre");
    vi.mocked(fetchLatestAssets).mockResolvedValue([source, jdk, jre]);
    const result = await loadLatestAssets(25, "any", "any");
    expect([...result]).toEqual([jdk, jre]);
    expect(result.source).toEqual(source);
    expect(fetchLatestAssets).toHaveBeenCalledWith(25, {});
  });

  it("preserves API order and metadata", async () => {
    const first = createMockTemurinReleaseAPI(false, "jdk");
    const second = {
      ...createMockTemurinReleaseAPI(false, "jdk"),
      release_name: "newer-release",
    };
    vi.mocked(fetchLatestAssets).mockResolvedValue([first, second]);
    expect(await loadLatestAssets(21, "any", "any")).toEqual([first, second]);
  });

  it("propagates request failures so the page can show a retry action", async () => {
    const error = new Error("API unavailable");
    vi.mocked(fetchLatestAssets).mockRejectedValue(error);
    await expect(loadLatestAssets(25, "linux", "x64")).rejects.toThrow(error);
  });

  it.each([
    {
      version: {
        major: 17,
        minor: 0,
        security: 9,
        build: 9,
        adopt_build_number: 1,
      },
      short: false,
      expected: "17.0.9+9.1",
    },
    {
      version: { major: 20, minor: 0, security: 0, build: 36, patch: 0 },
      short: false,
      expected: "20.0.0+36",
    },
    {
      version: { major: 20, minor: 0, security: 0, build: 36, patch: 0 },
      short: true,
      expected: "20+36",
    },
    {
      version: { major: 18, minor: 0, security: 2, build: 1, patch: 1 },
      short: false,
      expected: "18.0.2.1+1",
    },
  ])("formats version $expected", ({ version, short, expected }) => {
    expect(getVersionAsString(version, short)).toBe(expected);
  });
});
